char* validate_chunk(const char* chunk, size_t len) {
  // naive echo-wrapped result for illustration
  const char* fmt = "{\"valid\":true,\"len\":%zu,\"payload\":%.*s}";
  size_t needed = snprintf(NULL, 0, fmt, len, (int)len, chunk) + 1;
  char* out = (char*)malloc(needed);
